import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { brokeredPreviewStorage } from './previewAuthStorage';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

const isValidSupabaseUrl = (value: string | undefined): boolean => {
  if (!value) return false;
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.hostname === "localhost" || url.hostname === "127.0.0.1";
  } catch {
    return false;
  }
};

export const isSupabaseConfigured = Boolean(
  isValidSupabaseUrl(SUPABASE_URL) &&
    !SUPABASE_URL?.includes("your-project-ref") &&
    SUPABASE_PUBLISHABLE_KEY?.trim() &&
    !SUPABASE_PUBLISHABLE_KEY.trim().startsWith("your-"),
);

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

// The local setup screen can render without credentials. Auth and data routes
// are mounted only after real Supabase configuration is present.
export const supabase = createClient<Database>(
  isSupabaseConfigured ? SUPABASE_URL! : "http://127.0.0.1:54321",
  isSupabaseConfigured ? SUPABASE_PUBLISHABLE_KEY! : "supabase-not-configured",
  {
  auth: {
    storage: brokeredPreviewStorage(),
    persistSession: true,
    autoRefreshToken: true,
  }
  },
);
